import csv
from datetime import datetime
path='/home/agent/workspace/bookstore_orders.csv'
stats={}
with open(path, newline='', encoding='utf-8') as f:
    reader=csv.DictReader(f)
    for row in reader:
        if row['fulfillment_status'].strip().lower()!='delivered':
            continue
        carrier=row['carrier_name'].strip() or 'Unknown'
        est_str=row['estimated_delivery_date'].strip()
        act_str=row['actual_delivery_date'].strip()
        if not est_str or not act_str:
            continue
        try:
            est_date=datetime.strptime(est_str, '%Y-%m-%d').date()
            # actual may have time
            act_date=datetime.strptime(act_str.split()[0],'%Y-%m-%d').date()
        except:
            # try parsing with time
            try:
                est_date=datetime.strptime(est_str.split()[0],'%Y-%m-%d').date()
                act_date=datetime.strptime(act_str.split()[0],'%Y-%m-%d').date()
            except:
                continue
        if carrier not in stats:
            stats[carrier]={'total':0,'ontime':0}
        stats[carrier]['total']+=1
        if act_date <= est_date:
            stats[carrier]['ontime']+=1
rows=[]
for carrier,data in stats.items():
    total=data['total']
    ont=data['ontime']
    pct=round(ont/total*100,2) if total else 0.0
    rows.append({'CarrierName':carrier,'TotalDelivered':total,'OnTimeDelivered':ont,'OnTimePct':pct})
rows.sort(key=lambda x: x['OnTimePct'], reverse=True)
out_path='/home/agent/workspace/carrier-otd.csv'
with open(out_path,'w',newline='',encoding='utf-8') as out:
    writer=csv.DictWriter(out, fieldnames=['CarrierName','TotalDelivered','OnTimeDelivered','OnTimePct'])
    writer.writeheader()
    for r in rows:
        writer.writerow(r)
print('written')
for r in rows:
    print(r)
