            denominator < 60 -> denominator
            denominator % 60 == 0L -> denominator
            denominator % 30 == 0L -> denominator
            else -> {
                val candidates = listOf(1L, 2, 4, 5, 8, 10, 15, 20, 25, 30, 50, 60, 100, 125, 150, 200, 250, 300, 500, 1000)
