def _parse_fen(fen: str):
    parts = fen.split()
    placement = parts[0]
    active = parts[1] if len(parts) > 1 else 'w'
    rights = parts[2] if len(parts) > 2 else '-'
    ep_str = parts[3] if len(parts) > 3 else '-'
    board = []
    for rank_str in placement.split('/'):
        row = []
        for ch in rank_str:
            if ch.isdigit():
                row.extend([None] * int(ch))
            else:
                row.append(ch)
        board.append(row)
    ep = None
    if ep_str and ep_str != '-':
        col = ord(ep_str[0]) - ord('a')
        row = 8 - int(ep_str[1])
        ep = (row, col)
    return board, active, rights, ep

def _square_name(r: int, c: int) -> str:
