    return None, None

def _square_attacked(board, target_r, target_c, by_white):
    for r in range(8):
        for c in range(8):
            piece = board[r][c]
            if piece is None:
                continue
            if piece.isupper() != by_white:
                continue
            ptype = piece.upper()
            if ptype == 'P':
                direction = -1 if by_white else 1
                if r + direction == target_r and abs(c - target_c) == 1:
                    return True
            elif ptype == 'N':
                if (abs(r - target_r), abs(c - target_c)) in [(1,2),(2,1)]:
                    return True
            elif ptype == 'K':
                if max(abs(r - target_r), abs(c - target_c)) == 1:
                    return True
            elif ptype in ('B','R','Q'):
                if ptype in ('B','Q') and abs(r - target_r) == abs(c - target_c):
                    step_r = 1 if target_r > r else -1
                    step_c = 1 if target_c > c else -1
                    cur_r, cur_c = r + step_r, c + step_c
                    blocked = False
                    while (cur_r, cur_c) != (target_r, target_c):
                        if board[cur_r][cur_c] is not None:
                            blocked = True
                            break
                        cur_r += step_r
                        cur_c += step_c
                    if not blocked:
                        return True
                if ptype in ('R','Q') and (r == target_r or c == target_c):
                    step_r = 0 if r == target_r else (1 if target_r > r else -1)
                    step_c = 0 if c == target_c else (1 if target_c > c else -1)
                    cur_r, cur_c = r + step_r, c + step_c
                    blocked = False
                    while (cur_r, cur_c) != (target_r, target_c):
                        if board[cur_r][cur_c] is not None:
                            blocked = True
                            break
                        cur_r += step_r
                        cur_c += step_c
                    if not blocked:
                        return True
