def _castling_right_char(white, r, c):
    if white:
        if r == 7 and c == 7:
            return 'K'
        if r == 7 and c == 0:
            return 'Q'
    else:
        if r == 0 and c == 7:
            return 'k'
        if r == 0 and c == 0:
