    if piece and piece.upper() == 'R':
        rc = _castling_right_char(active_white, r1, c1)
        if rc:
            rights_set.discard(rc)
    if captured and captured.upper() == 'R':
        rc = _castling_right_char(not active_white, r2, c2)
        if rc:
