                        if not _square_attacked(board, row, kc+1, not active_white) and not _square_attacked(board, row, kc+2, not active_white):
                            moves.append((kr,kc,kr,kc+2,True,False,None))
                if 'Q' in rights:
                    if board[row][kc-1] is None and board[row][kc-2] is None and board[row][kc-3] is None and board[row][kc-4] == 'R':
                        if not _square_attacked(board, row, kc-1, not active_white) and not _square_attacked(board, row, kc-2, not active_white):
