def legal_moves(fen: str) -> list:
    board, active, rights, ep = _parse_fen(fen)
    active_white = active == 'w'
    moves = _generate_moves(board, active_white, rights, ep)
    uci = []
    for r1,c1,r2,c2,is_castle,is_ep,promo in moves:
        u = f"{_square_name(r1,c1)}{_square_name(r2,c2)}"
        if promo:
            u += promo.lower()
        uci.append(u)
    return uci

def _perft_rec(board, active_white, rights, ep_target, depth):
    if depth == 0:
        return 1
    total = 0
    moves = _generate_moves(board, active_white, rights, ep_target)
    for r1,c1,r2,c2,is_castle,is_ep,promo in moves:
        new_board = [row[:] for row in board]
        piece = new_board[r1][c1]
        captured = new_board[r2][c2]
        new_board[r1][c1] = None
        # handle promotion
        if promo:
            new_piece = promo if active_white else promo.lower()
            new_board[r2][c2] = new_piece
        else:
            new_board[r2][c2] = piece if not is_ep else None
        if is_castle:
            if c2 == c1 + 2:
                rook_from_c = c1 + 3
                rook_to_c = c1 + 1
            else:
                rook_from_c = c1 - 4
                rook_to_c = c1 - 1
            row = r1
            rook = new_board[row][rook_from_c]
            new_board[row][rook_from_c] = None
            new_board[row][rook_to_c] = rook
        if is_ep:
            cap_r = r1
            cap_c = c2
            new_board[cap_r][cap_c] = None
        new_rights = _update_rights(rights, active_white, r1,c1,r2,c2, piece, None if is_ep or promo else captured)
        ep_next = None
        if piece and piece.upper() == 'P' and abs(r2 - r1) == 2:
            direction = -1 if active_white else 1
            ep_next = (r1 + direction, c1)
        total += _perft_rec(new_board, not active_white, new_rights, ep_next, depth-1)
    return total

def perft(fen: str, depth: int) -> int:
    board, active, rights, ep = _parse_fen(fen)
    active_white = active == 'w'
    return _perft_rec(board, active_white, rights, ep, depth)

