    start = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1"
    print("legal moves count:", len(legal_moves(start)))
    print("perft depth 1:", perft(start, 1))
    print("perft depth 2:", perft(start, 2))
